"""Dispatch: pallet reconciliation queue. Jobs arrive from the gateway (scanner moves and controller
activity) and are applied to the ledger by a small worker pool."""
import json
import os
import sqlite3
import sys
import threading
import time
import uuid

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import netutil  # noqa: E402
from common.config import load  # noqa: E402
from common.httpd import JSONHandler, serve  # noqa: E402
from common.logutil import setup  # noqa: E402

cfg = load()
log = setup("dispatch", cfg.get("LOG_LEVEL", "INFO"))
LEDGER = cfg["LEDGER_URL"]
QUEUE_DB = cfg["DISPATCH_QUEUE_DB"]
WORKERS = int(cfg.get("DISPATCH_WORKERS", 2))
WMS_LOOKUP_S = float(cfg.get("WMS_LOOKUP_S", 20))
POLL_S = float(cfg.get("DISPATCH_POLL_S", 15))
_tls = threading.local()
_wms_lock = threading.Lock()
_enq_lock = threading.Lock()
_enq_conn = None


def qdb():
    conn = getattr(_tls, "conn", None)
    if conn is None:
        conn = sqlite3.connect(QUEUE_DB, timeout=5, isolation_level=None)
        conn.row_factory = sqlite3.Row
        _tls.conn = conn
    return conn


def init():
    c = sqlite3.connect(QUEUE_DB)
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("CREATE TABLE IF NOT EXISTS jobs (job_id TEXT PRIMARY KEY, kind TEXT, payload TEXT, state TEXT, created_at TEXT, started_at TEXT, done_at TEXT, worker TEXT)")
    c.commit(); c.close()


def wms_pallet_lookup(lot):
    """Weight/dimension lookup against the WMS export. Slow link, one lookup at a time (the export is a
    single file opened exclusively); runs inline for now (TODO async)."""
    with _wms_lock:
        time.sleep(WMS_LOOKUP_S)
    return {"lot": lot, "ok": True}


class H(JSONHandler):
    routes = {}


def post_jobs(h, path, body):
    job_id = uuid.uuid4().hex[:12]
    if body.get("kind") == "pallet_move":
        wms_pallet_lookup(body.get("lot"))
    global _enq_conn
    with _enq_lock:
        if _enq_conn is None:
            _enq_conn = sqlite3.connect(QUEUE_DB, timeout=30, isolation_level=None, check_same_thread=False)
        _enq_conn.execute("INSERT INTO jobs(job_id, kind, payload, state, created_at) VALUES (?,?,?,?,?)",
                          (job_id, body.get("kind", "unknown"), json.dumps(body), "queued", netutil.now_iso()))
    log.info("job queued id=%s kind=%s lot=%s", job_id, body.get("kind"), body.get("lot"))
    return 202, {"job_id": job_id}


def get_jobs(h, path, body):
    return 200, {"jobs": [dict(r) for r in qdb().execute("SELECT job_id, kind, state, created_at, done_at FROM jobs ORDER BY created_at DESC LIMIT 200")]}


def get_health(h, path, body):
    n = qdb().execute("SELECT COUNT(*) FROM jobs WHERE state='queued'").fetchone()[0]
    return 200, {"ok": True, "queued": n}


H.routes = {("POST", "/jobs"): post_jobs, ("GET", "/jobs"): get_jobs, ("GET", "/health"): get_health}


def apply_move(job_id, p, worker):
    lot, to_zone, from_zone = p["lot"], p["to"], p.get("from")
    status, cur = netutil.http_call(f"{LEDGER}/lots/{lot}", "GET", timeout_s=20)
    if status != 200:
        log.error("[%s] job %s: lot %s not found in ledger (%s)", worker, job_id, lot, status)
        return
    if from_zone and cur["zone"] != from_zone:
        log.warning("[%s] job %s: zone mismatch for %s: scanner says from=%s, ledger has %s; applying move to %s anyway",
                    worker, job_id, lot, from_zone, cur["zone"], to_zone)
    time.sleep(0.5)  # audit trail write-behind
    status, _ = netutil.http_call(f"{LEDGER}/lots/{lot}/zone", "PUT",
                                  {"zone": to_zone, "from_zone": cur["zone"], "operator": p.get("operator"), "job_id": job_id,
                                   "note": None if not from_zone or cur["zone"] == from_zone else f"scanner from={from_zone}"},
                                  timeout_s=20)
    if status >= 300:
        log.error("[%s] job %s: ledger update failed (%s)", worker, job_id, status)
    else:
        log.info("[%s] job %s applied: %s %s->%s", worker, job_id, lot, cur["zone"], to_zone)


def reconcile(job_id, p, worker):
    # activity events: nothing to apply, but make sure the zone is known to the ledger
    time.sleep(1.0)
    log.debug("[%s] job %s reconcile zone=%s ok", worker, job_id, p.get("zone"))


def worker_loop(name):
    while True:
        conn = qdb()
        row = conn.execute("SELECT job_id, kind, payload FROM jobs WHERE state='queued' ORDER BY created_at LIMIT 1").fetchone()
        if row is None:
            time.sleep(POLL_S)
            continue
        cur = conn.execute("UPDATE jobs SET state='running', started_at=?, worker=? WHERE job_id=? AND state='queued'", (netutil.now_iso(), name, row["job_id"]))
        if cur.rowcount == 0:
            continue
        p = json.loads(row["payload"])
        try:
            if row["kind"] == "pallet_move":
                apply_move(row["job_id"], p, name)
            else:
                reconcile(row["job_id"], p, name)
        except Exception as e:  # noqa: BLE001
            log.error("[%s] job %s failed: %s", name, row["job_id"], e)
        conn.execute("UPDATE jobs SET state='done', done_at=? WHERE job_id=?", (netutil.now_iso(), row["job_id"]))


def main():
    init()
    for i in range(WORKERS):
        threading.Thread(target=worker_loop, args=(f"w{i + 1}",), daemon=True).start()
    log.info("dispatch serving %s:%s workers=%d", cfg["DISPATCH_HOST"], cfg["DISPATCH_PORT"], WORKERS)
    serve(H, cfg["DISPATCH_HOST"], int(cfg["DISPATCH_PORT"])).serve_forever()


if __name__ == "__main__":
    main()
"""Alerting: polls the ledger, evaluates threshold rules per zone, posts to chat channels via the
notifier and records alerts in the ledger."""
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import netutil  # noqa: E402
from common.config import load  # noqa: E402
from common.logutil import setup  # noqa: E402

cfg = load()
log = setup("alerting", cfg.get("LOG_LEVEL", "INFO"))
LEDGER = cfg["LEDGER_URL"]
POLL_S = int(cfg.get("ALERT_POLL_S", 60))
SEVERITY_RANK = {"info": 0, "warning": 1, "critical": 2}
HERE = os.path.dirname(os.path.abspath(__file__))
_active = {}
_routes_mtime = 0.0
_routes = {}


def routes():
    """alerting/routes.json is re-read when it changes so hotfixes do not need a restart."""
    global _routes, _routes_mtime
    path = os.path.join(HERE, "routes.json")
    try:
        m = os.path.getmtime(path)
    except OSError:
        return _routes
    if m != _routes_mtime:
        with open(path) as f:
            _routes = json.load(f)
        _routes_mtime = m
        log.info("routes loaded: %s", json.dumps({z: v.get("channel") for z, v in _routes.get("zones", {}).items()}))
    return _routes


def notify(channel, text):
    """Chat notifier. Channels that have been archived accept the post but nobody sees it."""
    log.info("POST %s: %s", channel, text)


def evaluate(latest):
    r = routes()
    min_sev = str(load().get("ALERT_MIN_SEVERITY", r.get("min_severity", "warning"))).lower()
    for row in latest:
        zone = row.get("zone")
        if zone is None or zone not in r.get("zones", {}):
            continue
        zr = r["zones"][zone]
        v = row.get("air_temp")
        if v is None:
            continue
        fired = None
        if v > zr["high"]:
            fired = ("high_temp", "critical", v)
        elif v < zr["low"]:
            fired = ("low_temp", "warning", v)
        key = (zone, fired[0]) if fired else None
        for (z, rule), a in list(_active.items()):
            if z == zone and (fired is None or rule != fired[0]):
                log.info("cleared alert=%s zone=%s rule=%s value=%s", a["alert_id"], z, rule, v)
                netutil.http_call(LEDGER + "/alerts", "POST", {"alert_id": a["alert_id"], "state": "cleared"}, timeout_s=20)
                del _active[(z, rule)]
        if fired and key not in _active:
            rule, sev, val = fired
            alert_id = f"AL-{int(time.time()) % 100000:05d}-{zone}"
            channel = zr.get("channel", r.get("default_channel"))
            if SEVERITY_RANK[sev] < SEVERITY_RANK.get(min_sev, 1):
                log.debug("suppressed alert zone=%s rule=%s severity=%s value=%.1f (min_severity=%s)", zone, rule, sev, val, min_sev)
                continue
            _active[key] = {"alert_id": alert_id}
            log.warning("raised alert=%s zone=%s rule=%s severity=%s value=%.1f channel=%s", alert_id, zone, rule, sev, val, channel)
            notify(channel, f"[{sev.upper()}] zone {zone} {rule.replace('_', ' ')}: {val:.1f} C (limits {zr['low']}..{zr['high']})")
            netutil.http_call(LEDGER + "/alerts", "POST", {"alert_id": alert_id, "zone": zone, "rule": rule, "severity": sev, "value": val, "channel": channel}, timeout_s=20)


def main():
    log.info("alerting started poll=%ss", POLL_S)
    while True:
        try:
            status, body = netutil.http_call(LEDGER + "/readings/latest", "GET", timeout_s=20)
            if status == 200:
                evaluate(body.get("latest", []))
            else:
                log.error("ledger poll failed: %s", status)
        except (netutil.CallTimeout, ConnectionError, OSError) as e:
            log.error("ledger poll error: %s", e)
        time.sleep(POLL_S)


if __name__ == "__main__":
    main()
"""Ledger: the system of record (SQLite). Everything else talks to it over HTTP; billing is the
exception and opens the file directly (historical, see billing/nightly.py)."""
import json
import os
import sqlite3
import sys
import threading

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import netutil  # noqa: E402
from common.config import load  # noqa: E402
from common.httpd import JSONHandler, serve  # noqa: E402
from common.logutil import setup  # noqa: E402

cfg = load()
log = setup("ledger", cfg.get("LOG_LEVEL", "INFO"))
DB_PATH = cfg["LEDGER_DB"]
BUSY_TIMEOUT_S = float(cfg.get("LEDGER_BUSY_TIMEOUT_S", 5))
_tls = threading.local()
_pool = []
_pool_lock = threading.Lock()


class _Pooled:
    """Borrow a connection from a small pool for the duration of one request (request threads are short-lived)."""

    def __enter__(self):
        with _pool_lock:
            self.conn = _pool.pop() if _pool else None
        if self.conn is None:
            self.conn = sqlite3.connect(DB_PATH, timeout=BUSY_TIMEOUT_S, isolation_level=None, check_same_thread=False)
            self.conn.row_factory = sqlite3.Row
        return self.conn

    def __exit__(self, *a):
        with _pool_lock:
            if len(_pool) < 8:
                _pool.append(self.conn)
            else:
                self.conn.close()


def db():
    conn = getattr(_tls, "conn", None)
    if conn is None:
        with _pool_lock:
            conn = _pool.pop() if _pool else None
        if conn is None:
            conn = sqlite3.connect(DB_PATH, timeout=BUSY_TIMEOUT_S, isolation_level=None, check_same_thread=False)
            conn.row_factory = sqlite3.Row
        _tls.conn = conn
    return conn


def release():
    conn = getattr(_tls, "conn", None)
    if conn is not None:
        _tls.conn = None
        with _pool_lock:
            if len(_pool) < 8:
                _pool.append(conn)
                return
        conn.close()


def init():
    conn = sqlite3.connect(DB_PATH, timeout=BUSY_TIMEOUT_S)
    conn.execute("PRAGMA journal_mode=WAL")
    with open(os.path.join(os.path.dirname(__file__), "schema.sql")) as f:
        conn.executescript(f.read())
    conn.commit()
    conn.close()


def rows(cur):
    return [dict(r) for r in cur.fetchall()]


class H(JSONHandler):
    routes = {}

    def _dispatch(self, method):
        try:
            return super()._dispatch(method)
        finally:
            release()


def post_readings(h, path, body):
    try:
        conn = db()
        conn.execute(
            "INSERT INTO readings(ctrl_id, seq, recv, zone, air_temp, comp_state, setpoint, unknown_tokens, raw) VALUES (?,?,?,?,?,?,?,?,?)",
            (body["ctrl_id"], body["seq"], body["recv"], body.get("zone"), body.get("air_temp"), body.get("comp_state"),
             body.get("setpoint"), json.dumps(body.get("unknown") or []), body["raw"]))
        if body.get("zone") and body.get("air_temp") is not None:
            conn.execute("INSERT INTO latest_readings(zone, recv, air_temp, comp_state, seq, ctrl_id) VALUES (?,?,?,?,?,?) "
                         "ON CONFLICT(zone) DO UPDATE SET recv=excluded.recv, air_temp=excluded.air_temp, comp_state=excluded.comp_state, seq=excluded.seq, ctrl_id=excluded.ctrl_id",
                         (body["zone"], body["recv"], body["air_temp"], body.get("comp_state"), body["seq"], body["ctrl_id"]))
    except sqlite3.OperationalError as e:
        log.error("readings insert failed ctrl=%s seq=%s: %s", body.get("ctrl_id"), body.get("seq"), e)
        return 503, {"error": str(e)}
    return 201, {"ok": True}


def get_readings_latest(h, path, body):
    out = rows(db().execute("SELECT zone, recv, air_temp, comp_state FROM latest_readings ORDER BY zone"))
    return 200, {"latest": out}


